        const dg2 = x.createRadialGradient(cx - R * 0.4, cy - R * 0.4, R * 0.1, cx, cy, R);
        dg2.addColorStop(0, mix3("#ffffff", P.accent, 0.2));
        dg2.addColorStop(0.6, P.accent);
