        const dg2 = x.createRadialGradient(cx, cy, 0, cx, cy, R * 0.7);
        dg2.addColorStop(0, mix3("#ffffff", P.lit, 0.2));
        dg2.addColorStop(1, mix3(P.lit, P.sky0, 0.6));
