        const nearSrc = sourceXs.length && r() < 0.42;
        let bx0;
        if (nearSrc) {
          const sx = sourceXs[Math.floor(r() * sourceXs.length)];
          bx0 = sx + K10.randn(r) * (W * 0.16);
        } else bx0 = r() * W;
        const rise = Math.pow(r(), nearSrc ? 1.5 : 1.12);
        const ey = botY - rise * (botY - topY);
        const fl = K10.curl(noise, bx0 * 0.7, ey * 0.7, 2);
        const wander = fl[0] * (60 + rise * W * spread) + K10.randn(r) * (20 + rise * W * spread * 0.6);
        const ex = bx0 + wander;
        if (ex < -10 || ex > W + 10) continue;
        let col, a, sz;
        if (rise < 0.4) {
          col = r() < 0.35 ? P.white : P.hot;
          a = 0.45 + r() * 0.45;
          sz = 0.6 + r() * 1.7;
        } else if (rise < 0.72) {
          col = K10.mix(P.hot, aur, (rise - 0.4) / 0.32);
          a = 0.28 + r() * 0.32;
          sz = 0.5 + r() * 1.3;
        } else {
          col = K10.mix(aur, P.aur1, r());
          a = 0.1 + r() * 0.2;
          sz = 0.4 + r() * 0.9;
        }
        const ang = Math.atan2(-1, fl[0] * 1.2);
        const len = (1.5 + rise * 5) * (0.5 + r());
        x.strokeStyle = K10.rgba(col, a);
        x.lineWidth = sz;
        x.lineCap = "round";
        x.beginPath();
        x.moveTo(ex, ey);
        x.lineTo(ex + Math.cos(ang) * len, ey + Math.sin(ang) * len);
        x.stroke();
