      auroraSky(x, P, W, H, aur, noise, r, seed, H * 0, horizon * 0.86, K10.rint(r, 3, 5), 1);
      smokestacks(x, P, W, H, aur, noise, r, horizon, K10.rint(r, 6, 11), 1, 1);
      if (p.anom === "Aurora Bleed") auroraColumn(x, P, W, H, aur, noise, r, W * p.focusX, H * 0.16, horizon + H * 0.1);
