      x.lineTo(W, HZ);
      x.closePath();
      x.fill();
      for (let i = 0; i < 3; i++) {
        const cx = i === 1 ? W * (0.15 + r() * 0.12) : W * (0.78 + r() * 0.14);
        const by = HZ + 14 + r() * 18;
        topiary(x, P, cx, by, 40 + r() * 30, 60 + r() * 40, K10.pick(SHAPES, r), 0.35, K10.rng(seed + i * 13 >>> 0));
      }
      const shape = p.shapeBias;
      const hw = W * (0.44 + r() * 0.12);
      const hh = (HZ - HZ * 0.02) * (0.92 + r() * 0.18);
