      const hby = H * (0.95 + r() * 0.02);
      K10.bloom(x, hx2, hby - hh * 0.55, hw * 0.8, P.node, blue ? 0.12 : 0.08);
      topiary(x, P, hx2, hby, hw, hh, shape, 1, K10.rng(seed * 7 + 1 >>> 0), { detail: 2, rim: true });
      fountain(x, P, hx2, hby - hh * 0.04, hw * 0.2, r);
