      const moonX = side < 0 ? W * 0.72 : W * 0.28, moonY = HZ * (0.4 + r() * 0.3);
      K10.bloom(x, moonX, moonY, W * 0.18, K10.mix(P.node, "#fff", 0.3), 0.16);
      x.save();
