      x.lineTo(W, HZ);
      x.closePath();
      x.fill();
      const ringN = K10.rint(r, 5, 7);
      const ring = [];
      for (let i = 0; i < ringN; i++) {
        const a = Math.PI + i / (ringN - 1) * Math.PI;
        const rad = W * 0.3;
        const tx = cx + Math.cos(a) * rad, ty = cy + Math.sin(a) * rad * 0.34;
        const depth = K10.clamp(0.4 + (ty - HZ) / (H - HZ) * 0.6, 0.2, 1);
        const sz = 50 + depth * 90;
        ring.push({ cx: tx, by: ty + sz * 0.2, w: sz, h: sz * (1 + r() * 0.4), shape: K10.pick(SHAPES, r), depth, useed: seed + i * 37 >>> 0 });
      }
