        x.globalCompositeOperation = "multiply";
        x.fillStyle = K10.rgba("#000", 0.25 + d * 0.2);
        x.beginPath();
        x.ellipse(bx + rad * 0.2, y + wallH + rad * 0.2, rad * 1.1, rad * 0.34, 0, 0, 7);
        x.fill();
        x.restore();
        const fromLeft = env.glowX < bx;
        const wallG = x.createLinearGradient(bx - rad, 0, bx + rad, 0);
        const lit = K10.mix(col, P.spark, 0.4), shade2 = K10.mix(col, "#000", 0.5);
        wallG.addColorStop(0, K10.rgba(fromLeft ? shade2 : lit, alpha));
        wallG.addColorStop(0.5, K10.rgba(col, alpha));
        wallG.addColorStop(1, K10.rgba(fromLeft ? lit : shade2, alpha));
        x.fillStyle = wallG;
        x.beginPath();
        x.moveTo(bx - rad, y);
        x.lineTo(bx - rad, y + wallH);
        x.ellipse(bx, y + wallH, rad, rad * 0.3, 0, Math.PI, 0, true);
