        lidG.addColorStop(0, K10.rgba(K10.mix(col, P.spark, 0.45), alpha));
        lidG.addColorStop(0.6, K10.rgba(col, alpha));
        lidG.addColorStop(1, K10.rgba(shade2, alpha));
        x.fillStyle = lidG;
        x.beginPath();
        x.ellipse(bx, y, rad, rad * 0.3, 0, 0, 7);
