      const dark = r() < 0.5;
      const c = dark ? K3.mix(pal.paper, pal.faint, 0.5) : K3.mix(pal.paper, "#fff", 0.5);
      const g = x.createRadialGradient(bx, by, 0, bx, by, br);
      g.addColorStop(0, K3.rgba(c, 0.05 + r() * 0.05));
      g.addColorStop(1, K3.rgba(c, 0));
